# Input definitions for 48 interactive experiments. Each key maps to an implemented renderer.
def sel(key,label,values):return dict(type='select',key=key,label=label,options=[(str(a),b) for a,b in values])
def ran(key,label,a,b,v,step=1):return dict(type='range',key=key,label=label,min=a,max=b,value=v,step=step)
def num(key,label,v,a=-8,b=8):return dict(type='number',key=key,label=label,value=v,min=a,max=b,step=1)
G=sel('group','点群',[('C3v','C₃v'),('C2v','C₂v'),('D4','D₄')])
A=sel('a','第一个表示',[('A₁','A₁'),('A₂','A₂'),('E','E')]);B=sel('b','第二个表示',[('E','E'),('A₁','A₁'),('A₂','A₂')])
N=ran('n','位置数 n',3,10,6); ORB=ran('orb','轨道序号',1,10,1)
LABS={}
def lab(k,title,prompt,controls,engine=None,source='',note=''):
 LABS[k]=dict(key=k,title=title,prompt=prompt,controls=controls,engine=engine or k,source=source,note=note)
lab('basis','换坐标，不换动作','先预测：把坐标基转45°，镜面操作的迹会改变吗？',[ran('angle','新基转角 / °',0,180,45)],source='rotation,reflect,mul,tr',note='矩阵在新基中的形式为SᵀDS；这里只使用正交换基。')
lab('representation','操作乘积与矩阵乘积同时核对','选择三角形的两个操作，比较连续变换与乘积矩阵。',[ran('a','操作A序号',0,5,1),ran('b','操作B序号',0,5,3)],source='permutations,mul,near')
lab('characters','特征标正交：类必须带权重','选择两行，观察逐类贡献如何相加为0或1。',[G,ran('a','行i',1,5,1),ran('b','行j',1,5,2)],source='chars,dot')
lab('reduction','把可约表示拆成不可约声部','输入C₃v的三个特征标，程序保留非整数以便发现错误。',[num('c0','χ(E)',3,0,20),num('c1','χ(C₃)',0),num('c2','χ(σᵥ)',1)],source='reduce')
lab('fourier','围圈的相位如何正交','改变n和波数k，观察复相位箭头相加。',[ran('n','循环群阶n',2,12,5),ran('k','波数k',0,11,1)],source='phaseSum',note='这里只画一个复不可约表示的相位；k按n取模。')
lab('commute','哈密顿量与对称操作是否对易','把破坏对称性的扰动从0逐渐调大，观察[H,R]。',[ran('delta','对称破缺δ',-2,2,0,.05),ran('angle','空间转角 / °',0,180,120)],source='rotation,mul,add,scale')
lab('degeneracy','二维伙伴的简并何时解除','E子空间H=εI；加入区分x、y的扰动会怎样？',[ran('delta','破缺δ',0,2,0,.02)],source='eig',note='示意模型H=diag(−δ,+δ)，不代表任意材料的实际能带。')
lab('products','直积不是直和','逐项乘特征标，再用正交关系约化。',[A,B],source='product,reduce')
lab('integral','正负面积为什么被对称性消去','切换奇偶函数，观察对称积分和全对称平均。',[sel('kind','函数',[('odd','x：奇函数'),('even','x²：偶函数'),('cancel','x²−1/3：偶但积分为0')]),ran('bound','积分半宽a',.2,2,1,.05)],source='dot',note='积分域为[−a,a]，对称性允许不代表积分必定非零。')
lab('selection','给跃迁选择偏振方向','初末态与算符的三重直积是否含A₁？',[sel('initial','初态',[('A₁','A₁'),('A₂','A₂'),('E','E')]),sel('final','末态',[('E','E'),('A₁','A₁'),('A₂','A₂')]),sel('operator','偏振',[('A₁','z偏振：A₁'),('E','面内偏振：(x,y)，E')])],source='permitted')
lab('salc','把三个人的声音分声部','改变组合，观察三处系数的正负与归一化。',[sel('basis','选择SALC',[('0','A₁：同相'),('1','E伙伴1'),('2','E伙伴2')])],engine='salc',source='salcs,orthonormal')
lab('projector','逐操作投影：保留什么，消去什么','选种子和目标表示，逐项显示求和过程。',[sel('irrep','目标',[('A₁','A₁'),('A₂','A₂'),('E','E')]),ran('seed','种子位置',1,3,1),ran('terms','已相加项数',1,6,6)],source='projectorTriangle,permutations')
lab('gram','投影后还要检查线性独立','三组种子投到E空间，最多只能留下几个独立向量？',[ran('seeds','输入种子数',1,3,3)],source='projectorTriangle,orthonormal')
lab('square','平方平面配体的四个声部','Eu有两条伙伴；查看它们与s、p、d轨道的匹配。',[sel('basis','选择SALC',[('0','A₁g'),('1','B₁g'),('2','Eu,x'),('3','Eu,y')])],engine='salc',source='salcs,orthonormal')
lab('tetra','四面体的A₁与T₂','切换四条正交组合，颜色表示相位，圆盘面积表示系数平方。',[sel('basis','选择SALC',[('0','A₁'),('1','T₂,x'),('2','T₂,y'),('3','T₂,z')])],engine='salc',source='salcs,orthonormal')
lab('huckel','搭图、对角化、看轨道','切换骨架与局部势，同时比较系数、能级、密度与键级。',[sel('kind','骨架',[('chain','链'),('ring','环'),('tmcb','四亚甲基环丁烷')]),N,ORB,ran('electrons','π电子数',0,20,6),ran('defect','1号位点α偏移',-2,2,0,.1)],engine='huckel',source='huckel,eig,observables')
lab('block','镜面对称把链矩阵拆成小块','先关闭破缺，观察偶/奇SALC之间交叉块为零。',[ran('delta','端点不对称势',0,2,0,.05)],source='huckel,mul,T')
lab('ring','环的相位波与电子占据','改变环大小和电子数，先判断是否闭壳层。',[N,ORB,ran('electrons','π电子数',0,20,6)],engine='huckel',source='huckel,occupations,observables')
lab('naphthalene','萘的10个轨道与11条连接','点击轨道序号，对照Hc=Ec残差、密度与π键级。',[ORB,ran('electrons','π电子数',0,20,10)],engine='huckel',source='graph,huckel,observables')
lab('avoided','同对称耦合与避免交叉','把两条未耦合能级拉近，改变V，观察最小劈裂。',[ran('detuning','能量差E₁−E₂',-4,4,0,.05),ran('coupling','相互作用V',0,1.5,.35,.02)],engine='avoided',source='levels')
lab('threecenter','从开链三中心连续走到闭合三角','把两端耦合从0调到β，看非键层如何变化。',[ran('closing','两端耦合 / β',0,1,0,.02),ran('orb','轨道序号',1,3,2),ran('electrons','电子数',0,6,4)],engine='huckel',source='huckel,eig,observables')
lab('electrocyclic','同旋与对旋：先明确相位和观察方向','切换4π/6π与热/光条件，比较对称允许的端基转动。',[sel('electrons','π电子数',[('4','4π'),('6','6π')]),sel('condition','条件',[('thermal','热'),('photo','光激发')]),sel('motion','转动',[('con','同旋'),('dis','对旋')]),ran('angle','端基转角 / °',0,90,45)],source='rotation',note='示意轨道相位连续性；不计算真实反应势垒或所有可能机制。')
lab('orbital','轨道截面中的正负瓣','选多项式和截面；看不到某瓣可能只是截面经过节点。',[sel('orbital','角函数',[('s','s'),('px','px'),('pz','pz'),('dxy','dxy'),('dxz','dxz'),('dx2','dx²−y²'),('dz2','dz²'),('fxyz','fxyz')]),sel('plane','截面',[('xy','xy'),('xz','xz'),('tilted','斜截面')])],source='dot',note='显示角函数乘统一高斯包络；不是带真实径向节点的氢样解。')
lab('octasalc','八面体六个σ基如何分成1+2+3','同时看SALC形状和系数正交。',[sel('basis','选择SALC',[(str(i),x) for i,x in enumerate(['A₁g','Eg,1','Eg,2','T₁u,x','T₁u,y','T₁u,z'])])],engine='salc',source='salcs,orthonormal')
lab('hybrid','sp³：等价局域方向来自不同原子轨道','查看一个杂化轨道的s、px、py、pz系数与指向。',[sel('basis','方向',[(str(i),'四面体方向'+str(i+1)) for i in range(4)])],source='salcs,orthonormal',note='构造基函数不等于断言真实分子采用某种纯杂化。')
lab('pimix','π供体与π受体如何移动金属d能级','追踪每个本征态的金属成分，而非固定把上支叫d轨道。',[ran('ligand','配体π或π*能量',-4,4,-2,.05),ran('coupling','π耦合t',0,2,.6,.02)],source='levels')
lab('wade','把骨架电子一本账算清楚','输入顶点数和已扣除外向键后的骨架电子，比较三类要求。',[ran('vertices','顶点数n',4,12,6),ran('electrons','骨架电子数',6,32,14)],source='dot',note='仅用于明确的主族骨架计数，不自动处理过渡金属簇的总价电子。')
lab('sandwich','五元环的k相位与上下环组合','选择k和上下环相位，观察环SALC和金属匹配。',[ran('k','环角波数k',0,2,1),sel('parity','上下环组合',[('plus','同号'),('minus','反号')]),ran('twist','相对扭角 / °',0,36,36)],source='graph',note='实cos角波示意；k>0还有sin伙伴。g/u判定需连同空间反演后的环位置与pz相位。')
lab('terms','45个d²微观态如何分布','按ML、MS枚举所有允许的两电子占据，检查谱项总维数。',[sel('shell','壳层',[('2','d²：45态'),('1','p²：15态')])],source='microstates')
lab('field','晶场分裂必须保持加权重心','切换Oh/Td；加入四方示意扰动，检查五轨道能量和。',[sel('shape','环境',[('octa','八面体Oh'),('tetra','四面体Td')]),ran('delta','分裂Δ',0,4,1.5,.05),ran('distortion','低对称扰动',-1,1,0,.02)],source='field')
lab('spin','Δ与配对能竞争：电子怎样落座','穷举10个自旋轨道占据，选最低简化模型能量。',[ran('electrons','d电子数',1,10,6),ran('delta','Δ/P（P=1）',0,3,.6,.05)],source='spinConfigurations',note='只含晶场单电子能量与每对电子P；不是完整Racah多重态计算。')
lab('laporte','反演对称性如何让d—d跃迁变暗','调大奇宇称混合参数，观察借强度的最低阶平方关系。',[ran('mix','奇宇称混合ε',0,.4,0,.01)],source='permitted',note='示意I∝ε²；纯电偶极近似及其他规则仍须检查。')
lab('spinor','2π回到箭头，4π回到自旋子','拖动角度，同时看Bloch方向与复振幅的符号。',[ran('angle','转动θ / °',0,720,360)],source='rotation',note='绘制初态|+x⟩绕z转动；整体相位不改变单态概率。')
lab('vibration','让水的三个方式动起来','选择对称伸缩、弯曲、反对称伸缩，暂停后观察瞬时位移。',[sel('mode','模式',[('symmetric','A₁ 对称伸缩'),('bend','A₁ 弯曲'),('antisymmetric','B₂ 反对称伸缩')]),ran('amplitude','示意振幅',0,.35,.16,.01)],source='waterMode',note='几何位移为质心固定、无刚体转动的对称性示意，不是由真实水力场拟合的正则模。')
lab('vibcount','从固定原子数算出振动表示','逐项核对水分子的χ3N与减去的平移、转动。',[ran('operation','操作序号',0,3,0)],source='reduce,chars')
lab('stretch','两个键长坐标如何变成对称/反对称','改变两个键伸长，投影到S+和S−。',[ran('s1','键1伸长',-1,1,.5,.05),ran('s2','键2伸长',-1,1,.5,.05)],source='dot')
lab('fg','质量和力常数共同决定频率','改变中心/端点质量与弹簧强度，观察质量加权本征模。',[ran('mass','中心质量',1,40,16),ran('endmass','端点质量',1,4,1,.1),ran('k1','弹簧k₁',.2,3,1,.05),ran('k2','弹簧k₂',.2,3,1,.05),ran('mode','模式序号（0为平移）',0,2,1)],source='spring,eig',note='一维三原子链的等价质量加权模型，用于解释G的质量作用；不冒充水的完整FG矩阵。')
lab('spectra','模式类型与IR/Raman活动性','切换教材分子，区分模式数、简并度和频率类型数。',[sel('model','分子',[('water','H₂O'),('carbonate','CO₃²⁻'),('ammonia','NH₃'),('methane','CH₄'),('sf6','SF₆'),('co2','CO₂')])],source='chars')
lab('fermi','Fermi共振：同对称频率混合与借强度','改变基频和倍频失谐；假设未耦合态1亮、态2暗。',[ran('detuning','两频率失谐',-3,3,0,.05),ran('coupling','非谐耦合V',0,1,.2,.02)],engine='avoided',source='levels',note='频率使用任意相对单位；不表示实际CO₂频率拟合。')
lab('lattice','同一晶格，不同原胞','改变a、b和夹角；开关整数剪切换基，比较同一格点集。',[ran('ratio','b/a',.6,1.8,1,.05),ran('angle','γ / °',45,135,90),sel('basis','基矢',[('old','a,b'),('shear','a,a+b：detU=1')])],source='dot')
lab('wallpaper','从一个带方向的基元生成平面图案','添加旋转、镜像或滑移，观察完整图案而非只看格子。',[sel('group','平面群示例',[(x,x) for x in ['p1','p2','pm','pg','p4','p4m','p6','p6m']])],source='permutations,reflect',note='使用一般位置的有向非对称小三角形；只演示所列8群，其余9群原图见原页。')
lab('bravais','中心化计数：不是把角点全部算进一胞','查看惯用胞中的格点位置、共享份额与格点数。',[sel('type','中心化',[('P','P 原始'),('I','I 体心'),('F','F 面心'),('C','C 底心')]),ran('angle','观察角 / °',0,360,30)],source='centered')
lab('restriction','为什么周期晶格没有五重轴','转角迹是否为整数？同时观察局部n重星形。',[ran('n','转轴阶n',1,12,5)],source='rotation,tr')
lab('seitz','操作的平移部分为什么不能直接相加','按顺序组合镜面/二重转动与分数平移，比较AB和BA。',[sel('kind','例子',[('glide','滑移g：g²=平移'),('noncommute','镜面与半格平移：AB≠BA'),('inversion','P−1：一般/特殊位置')]),ran('x','起点x',0,1,.13,.01),ran('y','起点y',0,1,.27,.01)],source='seitz,mv')
lab('screw','螺旋不是转完之后留在原高度','连续施加nₘ，跟踪未折回的高度。',[sel('axis','螺旋轴',[(x,x.replace('_','₍')+'）') for x in ['2_1','3_1','3_2','4_1','4_2','4_3','6_1','6_2','6_3','6_4','6_5']]),ran('steps','操作次数',0,12,3)],source='screw',note='图中高度以晶胞c为单位，未取模；n次后纯平移m个胞。')
lab('extinction','散射相位箭头如何相消','切换中心化或螺旋，改变hkl，直接计算复相位和。',[sel('type','平移关系',[('I','I格'),('F','F格'),('C','C格'),('P','P格'),('21','2₁轴的00l'),('41','4₁轴的00l'),('42','4₂轴的00l')]),num('h','h',1,-8,8),num('k','k',1,-8,8),num('l','l',1,-8,8)],source='phaseSum,centered,screw',note='相同散射因子的中心化相位因子；螺旋选项只检验00l，自动忽略h,k并明确标注。')
